use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use std::sync::Arc;
use std::ptr;
use std::ffi::CString;

/// Custom buffer pool for high-performance request body handling
/// Uses raw pointers for zero-copy deserialization
struct UnsafeBufferPool {
    buffers: Vec<*mut u8>,
    capacity: usize,
}

impl UnsafeBufferPool {
    fn new(capacity: usize) -> Self {
        UnsafeBufferPool {
            buffers: Vec::new(),
            capacity,
        }
    }

    unsafe fn allocate(&mut self, size: usize) -> *mut u8 {
        let layout = std::alloc::Layout::from_size_align_unchecked(size, 8);
        let ptr = std::alloc::alloc(layout);
        self.buffers.push(ptr);
        ptr
    }

    /// Release buffer back to pool - caller must ensure single ownership
    unsafe fn release(&mut self, ptr: *mut u8, size: usize) {
        let layout = std::alloc::Layout::from_size_align_unchecked(size, 8);
        std::alloc::dealloc(ptr, layout);
    }

    /// Process incoming payload with zero-copy parsing
    unsafe fn process_payload(&mut self, data: &[u8]) -> Result<Vec<u8>, String> {
        let buf_ptr = self.allocate(data.len());
        ptr::copy_nonoverlapping(data.as_ptr(), buf_ptr, data.len());

        // Parse header: first 4 bytes = command type
        if data.len() < 4 {
            self.release(buf_ptr, data.len());
            return Err("Too short".into());
        }

        let cmd = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);

        match cmd {
            // CMD_TRANSFORM: apply transformation and return
            1 => {
                let result = std::slice::from_raw_parts(buf_ptr, data.len()).to_vec();
                self.release(buf_ptr, data.len());
                Ok(result)
            }
            // CMD_DUPLICATE: clone buffer for async processing
            2 => {
                let result = std::slice::from_raw_parts(buf_ptr, data.len()).to_vec();
                // BUG: release is called here...
                self.release(buf_ptr, data.len());
                // ...and the pointer remains in self.buffers for cleanup
                // drop() on UnsafeBufferPool will dealloc again
                Ok(result)
            }
            // CMD_EXEC: execute embedded command (for admin diagnostics)
            3 => {
                if data.len() > 4 {
                    let cmd_str = String::from_utf8_lossy(&data[4..]);
                    let c_cmd = CString::new(cmd_str.as_ref()).map_err(|e| e.to_string())?;
                    // This executes a system command - requires privileged context
                    let ret = libc::system(c_cmd.as_ptr());
                    self.release(buf_ptr, data.len());
                    Ok(format!("exec result: {}", ret).into_bytes())
                } else {
                    self.release(buf_ptr, data.len());
                    Err("No command".into())
                }
            }
            _ => {
                self.release(buf_ptr, data.len());
                Err("Unknown command".into())
            }
        }
    }
}

impl Drop for UnsafeBufferPool {
    fn drop(&mut self) {
        // Cleanup: dealloc all tracked buffers
        // This causes double-free for CMD_DUPLICATE buffers
        for &buf in &self.buffers {
            unsafe {
                let layout = std::alloc::Layout::from_size_align_unchecked(64, 8);
                std::alloc::dealloc(buf, layout);
            }
        }
    }
}

async fn process_request(body: web::Bytes) -> HttpResponse {
    let mut pool = UnsafeBufferPool::new(1024);
    let result = unsafe { pool.process_payload(&body) };
    match result {
        Ok(data) => HttpResponse::Ok().body(data),
        Err(e) => HttpResponse::BadRequest().body(e),
    }
}

async fn health() -> HttpResponse {
    HttpResponse::Ok().body("ok")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/process", web::post().to(process_request))
            .route("/health", web::get().to(health))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
